WITH catalog_loss AS (SELECT cp.cp_catalog_page_id, cp.cp_department, r.r_reason_sk, r.r_reason_desc, SUM(cr.cr_net_loss) AS total_catalog_net_loss FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk GROUP BY cp.cp_catalog_page_id, cp.cp_department, r.r_reason_sk, r.r_reason_desc), store_loss AS (SELECT sr.sr_reason_sk AS reason_sk, SUM(sr.sr_net_loss) AS total_store_net_loss FROM store_returns sr GROUP BY sr.sr_reason_sk) SELECT cl.cp_catalog_page_id, cl.cp_department, cl.r_reason_desc, cl.total_catalog_net_loss, COALESCE(sl.total_store_net_loss, 0) AS total_store_net_loss, (cl.total_catalog_net_loss + COALESCE(sl.total_store_net_loss, 0)) AS combined_net_loss, CASE WHEN (cl.total_catalog_net_loss + COALESCE(sl.total_store_net_loss, 0)) > 150000 THEN 'High' WHEN (cl.total_catalog_net_loss + COALESCE(sl.total_store_net_loss, 0)) > 75000 THEN 'Medium' ELSE 'Low' END AS loss_category, DENSE_RANK() OVER (ORDER BY (cl.total_catalog_net_loss + COALESCE(sl.total_store_net_loss, 0)) DESC) AS loss_rank FROM catalog_loss cl LEFT JOIN store_loss sl ON cl.r_reason_sk = sl.reason_sk ORDER BY combined_net_loss DESC LIMIT 10
